const lat = Number(msg.req.query.lat);
const lon = Number(msg.req.query.lon);

if (
    !Number.isFinite(lat) ||
    !Number.isFinite(lon) ||
    lat < -90 ||
    lat > 90 ||
    lon < -180 ||
    lon > 180
) {
    msg.statusCode = 400;

    msg.payload = {
        ok: false,
        mensaje: "Latitud y longitud no válidas"
    };

    return [null, msg];
}

msg.latitud = lat;
msg.longitud = lon;

msg.url =
    "https://api.open-meteo.com/v1/forecast" +
    "?latitude=" + encodeURIComponent(lat) +
    "&longitude=" + encodeURIComponent(lon) +
    "&current=temperature_2m,precipitation,weather_code,wind_speed_10m" +
    "&timezone=auto";

return [msg, null];

let respuesta = msg.payload;

if (typeof respuesta === "string") {
    try {
        respuesta = JSON.parse(respuesta);
    } catch (error) {
        const estadoOriginal = msg.statusCode || null;

        msg.statusCode = 502;

        msg.payload = {
            ok: false,
            mensaje: "Open-Meteo devolvió una respuesta no válida",
            estado_open_meteo: estadoOriginal
        };

        return msg;
    }
}

if (!respuesta || !respuesta.current) {

    const estadoOriginal = msg.statusCode || null;

    msg.statusCode = 502;

    msg.payload = {
        ok: false,
        mensaje: "No se pudo obtener información meteorológica",
        estado_open_meteo: estadoOriginal,
        respuesta_open_meteo: respuesta || null
    };

    return msg;
}

const clima = respuesta.current;

msg.statusCode = 200;

msg.payload = {
    ok: true,
    latitud: respuesta.latitude,
    longitud: respuesta.longitude,
    temperatura: clima.temperature_2m,
    velocidad_viento: clima.wind_speed_10m,
    precipitacion: clima.precipitation,
    codigo_clima: clima.weather_code,
    fecha_hora_clima: clima.time
};

msg.headers = {
    "Content-Type": "application/json; charset=utf-8"
};

return msg;
